INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 6 > Kommunikation > Kommunikations-Modelle > Sender-Empfänger-Modell (Shannon-Weaver)
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Beschreibt das Sender-Empfänger-Modell von Shannon-Weaver Kommunikation als einen linearen Prozess?', 2, '[{"text": "Ja", "correct": true, "because": "Es zeigt einen Ablauf von Sender zu Empfänger"}, {"text": "Nein", "correct": false, "because": "Das Modell ist linear aufgebaut"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Störung (Rauschen) im Sender-Empfänger-Modell die Kommunikation beeinträchtigen?', 2, '[{"text": "Ja", "correct": true, "because": "Rauschen ist ein zentraler Faktor im Modell"}, {"text": "Nein", "correct": false, "because": "Störungen sind explizit berücksichtigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Rückkopplung ein integraler Bestandteil des ursprünglichen Shannon-Weaver-Modells?', 2, '[{"text": "Nein", "correct": true, "because": "Das Originalmodell ist ohne Feedback linear"}, {"text": "Ja", "correct": false, "because": "Feedback wurde später ergänzt"}]'),
('00000000-0000-0000-0000-0000-000000000000', 'Können technische Probleme laut Shannon-Weaver-Modell als Rauschen betrachtet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Rauschen umfasst alle Störfaktoren"}, {"text": "Nein", "correct": false, "because": "Technische Störungen sind Teil des Rauschens"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Sender-Empfänger-Modell ausschließlich für menschliche Kommunikation entwickelt worden?', 2, '[{"text": "Nein", "correct": true, "because": "Es wurde ursprünglich für technische Kommunikation entworfen"}, {"text": "Ja", "correct": false, "because": "Es stammt aus der Nachrichtentechnik"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt der Sender im Shannon-Weaver-Modell?', 3, '[{"text": "Er codiert die Nachricht", "correct": true, "because": "Der Sender wandelt Information in Signale um"}, {"text": "Er empfängt die Nachricht", "correct": false, "because": "Das ist die Rolle des Empfängers"}, {"text": "Er entfernt Störungen", "correct": false, "because": "Störungen sind extern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Begriff beschreibt im Shannon-Weaver-Modell Störungen im Kommunikationsprozess?', 2, '[{"text": "Rauschen", "correct": true, "because": "Rauschen ist jede Störung"}, {"text": "Kanal", "correct": false, "because": "Kanal ist Übertragungsmedium"}, {"text": "Decodierung", "correct": false, "because": "Das ist Empfängeraufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel des Sender-Empfänger-Modells?', 2, '[{"text": "Effiziente Übertragung von Informationen", "correct": true, "because": "Fokus auf Signalübertragung"}, {"text": "Emotionale Verbindung herstellen", "correct": false, "because": "Nicht Ziel des Modells"}, {"text": "Konflikte lösen", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann laut Shannon-Weaver-Modell die Kommunikation verhindern?', 3, '[{"text": "Starkes Rauschen", "correct": true, "because": "Verzerrt oder blockiert die Nachricht"}, {"text": "Schnelle Übertragung", "correct": false, "because": "Kein Fehler"}, {"text": "Automatische Codierung", "correct": false, "because": "Nicht problematisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponente wandelt die Nachricht im Shannon-Weaver-Modell wieder in verständliche Information um?', 2, '[{"text": "Empfänger", "correct": true, "because": "Der Empfänger decodiert"}, {"text": "Sender", "correct": false, "because": "Sender codiert"}, {"text": "Kanal", "correct": false, "because": "Kanal überträgt nur"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zum Shannon-Weaver-Modell?', 4, '[{"text": "Sender", "correct": true, "because": "Initiiert die Kommunikation"}, {"text": "Kanal", "correct": true, "because": "Übertragungsmedium"}, {"text": "Empfänger", "correct": true, "because": "Empfängt und decodiert"}, {"text": "Emotionen", "correct": false, "because": "Nicht Teil des technischen Modells"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Rauschen können im Shannon-Weaver-Modell auftreten?', 3, '[{"text": "Technisches Rauschen", "correct": true, "because": "Z. B. Signalstörungen"}, {"text": "Semantisches Rauschen", "correct": true, "because": "Z. B. Sprachprobleme"}, {"text": "Physisches Rauschen", "correct": true, "because": "Z. B. Umgebungslärm"}, {"text": "Emotionale Stimmung", "correct": false, "because": "Nicht im Modell enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prozesse sind im Shannon-Weaver-Modell enthalten?', 4, '[{"text": "Codierung", "correct": true, "because": "Sender wandelt Nachricht um"}, {"text": "Übertragung", "correct": true, "because": "Kanal leitet weiter"}, {"text": "Decodierung", "correct": true, "because": "Empfänger interpretiert"}, {"text": "Konfliktlösung", "correct": false, "because": "Nicht Teil des Modells"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme kann das Shannon-Weaver-Modell erklären?', 3, '[{"text": "Übertragungsfehler", "correct": true, "because": "Durch Rauschen verursacht"}, {"text": "Missverständnisse durch Störungen", "correct": true, "because": "Rauschen verzerrt"}, {"text": "Technische Kommunikationsausfälle", "correct": true, "because": "Fokus des Modells"}, {"text": "Emotionale Konflikte", "correct": false, "because": "Nicht berücksichtigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das Shannon-Weaver-Modell?', 3, '[{"text": "Klarheit über Kommunikationsprozess", "correct": true, "because": "Zeigt Ablauf"}, {"text": "Identifikation von Störquellen", "correct": true, "because": "Rauschen wird hervorgehoben"}, {"text": "Technische Optimierung", "correct": true, "because": "Ursprung in Nachrichtentechnik"}, {"text": "Förderung von Empathie", "correct": false, "because": "Kein Fokus des Modells"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das Shannon-Weaver-Modell betrachtet Kommunikation als linear. b) Emotionen sind ein zentraler Bestandteil des Modells.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Linear ja, Emotionen nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Rauschen kann die Nachricht im Shannon-Weaver-Modell verzerren. b) Der Empfänger codiert die Nachricht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Rauschen ja, Codierung durch Sender"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Shannon-Weaver-Modell wurde für technische Kommunikation entwickelt. b) Rückkopplung ist im ursprünglichen Modell enthalten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Technisch ja, Rückkopplung später"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Der Kanal überträgt die Nachricht im Shannon-Weaver-Modell. b) Das Modell berücksichtigt kulturelle Unterschiede.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kanal ja, Kultur nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Shannon-Weaver-Modell hilft, Störquellen zu identifizieren. b) Der Sender decodiert die Nachricht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Störquellen ja, Decodierung beim Empfänger"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

